CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(190) NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS competencies (id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,subject VARCHAR(100) NOT NULL,domain VARCHAR(150) NOT NULL,period VARCHAR(10) NOT NULL,reactivation VARCHAR(30),competency TEXT NOT NULL,objective TEXT NOT NULL,success_criteria TEXT,support TEXT,INDEX idx_subject(subject),INDEX idx_period(period)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS class_settings (id INT AUTO_INCREMENT PRIMARY KEY,school VARCHAR(190),teacher VARCHAR(190),class_name VARCHAR(80) DEFAULT 'CM1',student_count INT DEFAULT 0,school_year VARCHAR(20) DEFAULT '2026-2027',week_days JSON,day_start TIME,day_end TIME,breaks JSON,location VARCHAR(190) DEFAULT 'Mayotte',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS prep_sheets (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,competency_id INT NULL,objective TEXT NOT NULL,duration VARCHAR(30),materials TEXT,steps LONGTEXT,differentiation TEXT,assessment TEXT,notes TEXT,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_prep_comp FOREIGN KEY(competency_id) REFERENCES competencies(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sequences (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,subject VARCHAR(100),period VARCHAR(10),description TEXT,competency_ids JSON,session_plan LONGTEXT,assessment TEXT,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS journal_entries (id INT AUTO_INCREMENT PRIMARY KEY,entry_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,subject VARCHAR(100),competency_id INT NULL,prep_id INT NULL,sequence_id INT NULL,title VARCHAR(255) NOT NULL,objective TEXT,activity LONGTEXT,materials TEXT,differentiation TEXT,assessment TEXT,notes TEXT,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_journal_date(entry_date),CONSTRAINT fk_journal_comp FOREIGN KEY(competency_id) REFERENCES competencies(id) ON DELETE SET NULL,CONSTRAINT fk_journal_prep FOREIGN KEY(prep_id) REFERENCES prep_sheets(id) ON DELETE SET NULL,CONSTRAINT fk_journal_seq FOREIGN KEY(sequence_id) REFERENCES sequences(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS students (id INT AUTO_INCREMENT PRIMARY KEY,display_name VARCHAR(190) NOT NULL,sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_students_order(sort_order,display_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS supply_items (id INT AUTO_INCREMENT PRIMARY KEY,category VARCHAR(80) NOT NULL,label VARCHAR(255) NOT NULL,expected_quantity INT NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_supply_order(category,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS student_supply_status (id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,supply_item_id INT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'unchecked',missing_quantity INT NOT NULL DEFAULT 0,note VARCHAR(255) NULL,checked_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uniq_student_supply(student_id,supply_item_id),INDEX idx_supply_status(status),CONSTRAINT fk_supply_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,CONSTRAINT fk_supply_item FOREIGN KEY(supply_item_id) REFERENCES supply_items(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
